from pathlib import Path
import sys,shutil,subprocess
r=Path(sys.argv[1]);out=Path(sys.argv[2]);out.mkdir(parents=True,exist_ok=True)
for p in (r/'tests/release-fixtures/notification-jvm').rglob('*.java'):
 if p.name in ('NotificationJvm.java','NotificationSummary.java'):continue
 q=out/p.relative_to(r/'tests/release-fixtures/notification-jvm');q.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(p,q)
subprocess.run([sys.executable,str(r/'tests/release-fixtures/record-restore/extract.py'),str(r),str(out)],check=True)
