(out/'android/app/Notification.java').write_text('''package android.app;import android.content.*;import android.os.*;public class Notification{public static final int VISIBILITY_PRIVATE=0,GROUP_ALERT_CHILDREN=1;public static final String CATEGORY_MESSAGE="message",EXTRA_TITLE="android.title",EXTRA_TEXT="android.text",EXTRA_REMOTE_INPUT_HISTORY="history";public Bundle extras=new Bundle();public boolean reply;public String text;public long when=System.currentTimeMillis();public PendingIntent contentIntent;public Notification publicVersion;public Action[] actions;public static class Action{}public static class BigTextStyle{public BigTextStyle bigText(String s){return this;}}public static class Builder{Notification n=new Notification();public Builder(Context c,String ch){}public Builder setSmallIcon(int i){return this;}public Builder setContentTitle(CharSequence s){n.extras.put(EXTRA_TITLE,s);return this;}public Builder setContentText(CharSequence s){n.text=s==null?null:s.toString();n.extras.put(EXTRA_TEXT,s);return this;}public Builder setGroup(String s){return this;}public Builder setGroupAlertBehavior(int i){return this;}public Builder setStyle(BigTextStyle s){return this;}public Builder setContentIntent(PendingIntent p){n.contentIntent=p;return this;}public Builder setAutoCancel(boolean b){return this;}public Builder setOnlyAlertOnce(boolean b){return this;}public Builder setCategory(String s){return this;}public Builder setVisibility(int i){return this;}public Builder setPublicVersion(Notification v){n.publicVersion=v;return this;}public Builder reply(){n.reply=true;return this;}public Builder setWhen(long v){n.when=v;return this;}public Builder setSubText(String s){return this;}public Builder setGroupSummary(boolean b){return this;}public Builder setExtras(Bundle e){n.extras.putAll(e);return this;}public Builder setRemoteInputHistory(CharSequence[] c){return this;}public Builder addAction(Action a){return this;}public Notification build(){return n;}}}''',encoding='utf-8')
